macro.command:
// Dewdrop Shears - Add 1 Dewdrop Wool to the user's inventory
// Dewdrop Wool UUID: Item.XVbLJSEp07Wx5Pv1

const woolUuid = "Item.XVbLJSEp07Wx5Pv1";

// Try to find the actor from Midi-QOL / Item Macro / selected token / assigned character
const workflow = args?.[0];

let actor = null;

if (workflow?.actor) {
  actor = workflow.actor;
} else if (workflow?.actorUuid) {
  actor = await fromUuid(workflow.actorUuid);
} else if (typeof item !== "undefined" && item?.parent) {
  actor = item.parent;
} else if (canvas.tokens.controlled[0]?.actor) {
  actor = canvas.tokens.controlled[0].actor;
} else if (game.user.character) {
  actor = game.user.character;
}

if (!actor) {
  ui.notifications.warn("No actor found to receive the Dewdrop Wool.");
  return;
}

const sourceItem = await fromUuid(woolUuid);

if (!sourceItem) {
  ui.notifications.error("Could not find the Dewdrop Wool item. Check the Item UUID.");
  return;
}

const itemData = sourceItem.toObject();
itemData.system.quantity = 1;

// If the actor already has Dewdrop Wool, increase quantity instead of creating a duplicate
const existing = actor.items.find(i => i.name === sourceItem.name);

if (existing) {
  const currentQty = Number(existing.system.quantity ?? 0);
  await existing.update({ "system.quantity": currentQty + 1 });
} else {
  await actor.createEmbeddedDocuments("Item", [itemData]);
}

ChatMessage.create({
  speaker: ChatMessage.getSpeaker({ actor }),
  content: `<p><strong>${actor.name}</strong> carefully shears a Dewdrop Sheep and gains <strong>1 ${sourceItem.name}</strong>.</p>`
});

